<?php
require 'config.php';require_login();$pageTitle='Marks & results';$active='marks';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$sid=(int)($_POST['student_id']??0);$sub=trim($_POST['subject']??'');$im=(float)($_POST['internal_marks']??-1);$sm=(float)($_POST['semester_marks']??-1);if(!$sid||!$sub||$im<0||$im>100||$sm<0||$sm>100)$error='Choose a student and subject. Marks must be between 0 and 100.';else{$s=$conn->prepare('INSERT INTO marks(student_id,subject,internal_marks,semester_marks) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE internal_marks=VALUES(internal_marks),semester_marks=VALUES(semester_marks)');$s->bind_param('isdd',$sid,$sub,$im,$sm);$s->execute();flash('success','Marks saved successfully.');header('Location: marks.php');exit;}}
$students=$conn->query('SELECT id,register_number,name FROM students ORDER BY name');$rows=$conn->query('SELECT m.*,s.name,s.register_number FROM marks m JOIN students s ON s.id=m.student_id ORDER BY m.updated_at DESC');require 'includes/header.php';?>
<div class="heading"><div><p class="eyebrow">ACADEMIC PERFORMANCE</p><h1>Marks & results</h1><p class="muted">Record internal and semester marks for each subject.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<section class="card formcard"><div class="cardhead"><div><h2>Enter or update marks</h2><p class="muted">Saving the same subject again updates existing marks.</p></div></div><form method="post" class="formgrid"><label>Student *<select name="student_id" required><option value="">Select student</option><?php while($s=$students->fetch_assoc()):?><option value="<?=$s['id']?>"><?=e($s['register_number'].' — '.$s['name'])?></option><?php endwhile;?></select></label><label>Subject name *<input name="subject" required placeholder="e.g. Database Management Systems"></label><label>Internal marks (0–100) *<input type="number" name="internal_marks" min="0" max="100" step=".01" required></label><label>Semester marks (0–100) *<input type="number" name="semester_marks" min="0" max="100" step=".01" required></label><div class="actions"><button class="btn primary">Save marks →</button></div></form></section>
<section class="card"><div class="cardhead"><div><h2>Recorded marks <span class="count"><?=$rows->num_rows?></span></h2><p class="muted">Latest academic records.</p></div></div><div class="tablewrap"><table><thead><tr><th>STUDENT</th><th>SUBJECT</th><th>INTERNAL</th><th>SEMESTER</th><th>AVERAGE</th><th>RESULT</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):$avg=((float)$r['internal_marks']+(float)$r['semester_marks'])/2;?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['register_number'])?></small></td><td><?=e($r['subject'])?></td><td><?=number_format($r['internal_marks'],1)?></td><td><?=number_format($r['semester_marks'],1)?></td><td><b><?=number_format($avg,1)?>%</b></td><td><span class="badge <?=$avg>=40?'':'fail'?>"><?=$avg>=40?'Pass':'Needs review'?></span></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty">No marks recorded yet.</td></tr><?php endif;?></tbody></table></div></section><?php require 'includes/footer.php';?>